fn prepare(){assert!(!r("run-plan.json").exists());assert_eq!(read(r("native/result.json"))["status"],"complete");let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("build-pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}assert_eq!(hash(ACCEPTED),ACCEPTED_HASH);pin(&mut pins,ACCEPTED);let mut ids=BTreeMap::new();for(label,core)in[("control",124),("candidate",125)]{for(suite,count)in[("core",core),("prover",8)]{let p=r(format!("native/{suite}-{label}/tests.json"));let t=read(&p);assert_eq!(t["unfiltered"],true);assert_eq!(t["passed_tests"].as_array().unwrap().len(),count);pin(&mut pins,p);}let receipt=read(r(format!("native/{label}/artifacts.json")));assert_eq!(hash(receipt["binary"].as_str().unwrap()),receipt["binary_sha256"]);assert_eq!(receipt["libraries"].as_object().unwrap().len(),8);for(p,h)in receipt["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}let f=read(r(format!("frozen-{label}.json")));assert_eq!(f["rustflags"],fs::read_to_string(r(format!("native-flags-{label}.txt"))).unwrap());pin(&mut pins,r(format!("native/{label}/artifacts.json")));pin(&mut pins,r(format!("frozen-{label}.json")));}for v in VS{let binary=if v=="accepted"{PathBuf::from(ACCEPTED)}else if v=="OFF"{r("native/control-sdk")}else{r("native/candidate-sdk")};pin(&mut pins,&binary);ids.insert(v,json!({"binary":binary,"sha256":hash(&binary)}));}save(r("identities.json"),&json!(ids));let previous="/home/ubuntu/src/zopro-perf-work/g2-part-ready175/proof-sha256-after.json";let prior:BTreeSet<String>=serde_json::from_value(read(previous)).unwrap();assert_eq!(prior.len(),20755);save(r("prior-proof-sha256.json"),&json!(prior));pin(&mut pins,previous);
let mut cs=read("/home/ubuntu/src/zopro-perf-work/sdk-control-copies/cases.json").as_array().unwrap().clone();assert_eq!(cs.len(),9);let mut phys=cs[0].clone();phys["name"]=json!("1x2-w16");phys["workers"]=json!(16);phys["cpu_affinity"]=json!("0-15");cs.push(phys);save(r("cases.json"),&json!(cs));let base=read(MANIFEST)["environment"].clone();let mut jobs=vec![];let mut steps=vec![];let verifier=|j:&Value|{let c=&j["case"];let dir=Path::new(j["directory"].as_str().unwrap());json!({"kind":"command","name":format!("verify-{}",j["name"].as_str().unwrap()),"argv":[VERIFY,c["image"],c["image_sha256"],dir.join("0.proof"),dir.join("0.public"),c["public_sha256"]],"timeout_seconds":120})};for c in cs.iter().take(9){for v in VS{let j=push(c,v,0,true,&base,&ids,&mut jobs,&mut steps);steps.push(verifier(&j));}}for b in 0..31{let mut vs=VS;vs.rotate_left(b%3);if b%2!=0{vs.reverse();}for v in vs{push(&cs[0],v,b,false,&base,&ids,&mut jobs,&mut steps);}}assert_eq!(jobs.len(),120);for f in["ctl","ack"]{assert!(Command::new("mkfifo").arg(r(f)).status().unwrap().success());}for c in cs.iter().filter(|c|c["shape"]=="1x2"){for v in VS{diagnostic(c,v,"cycles",&base,&ids,&mut jobs,&mut steps);}}assert_eq!(jobs.len(),126);let owner=format!("{}:{}",output(&["id","-u"]).trim(),output(&["id","-g"]).trim());for j in jobs.iter().filter(|j|j["diagnostic"]==true){steps.push(json!({"kind":"command","name":format!("own-{}",j["name"].as_str().unwrap()),"argv":["sudo","-n","chown",owner,j["data"]],"timeout_seconds":30}));}for j in jobs.iter().filter(|j|j["preflight"]!=true){steps.push(verifier(j));}for j in jobs.iter().filter(|j|j["diagnostic"]==true){let name=j["name"].as_str().unwrap();steps.push(json!({"kind":"command","name":format!("decode-{name}"),"argv":["perf","script","--header","--show-lost-events","-i",j["data"],"-F","pid,tid,period,ip,sym"],"timeout_seconds":180}));steps.push(json!({"kind":"command","name":format!("evlist-{name}"),"argv":["perf","evlist","-v","-i",j["data"]],"timeout_seconds":30}));steps.push(json!({"kind":"command","name":format!("loss-{name}"),"argv":[r("capture-helper"),"loss",j["data"]],"timeout_seconds":180}));}assert_eq!(steps.len(),276);
fs::create_dir(r("codegen")).unwrap();for v in VS{let binary=ids[v]["binary"].as_str().unwrap();let out=Command::new("nm").args(["-S","--size-sort","--defined-only"]).arg(binary).output().unwrap();assert!(out.status.success());let text=String::from_utf8(out.stdout).unwrap();assert!(!text.contains("caller_probe"));let p=r(format!("codegen/{v}-symbols.txt"));fs::write(&p,&text).unwrap();pin(&mut pins,&p);let mut count=0;for line in text.lines().filter(|l|l.contains("g2_borrowed")&&l.contains("apply")||l.contains("stream_g1_impl")){let sym=line.split_whitespace().last().unwrap();let out=Command::new("objdump").args(["-d","--no-show-raw-insn"]).arg(format!("--disassemble={sym}")).arg(binary).output().unwrap();assert!(out.status.success());let body=String::from_utf8(out.stdout).unwrap();if !body.contains("vpmadd52"){continue;}let p=r(format!("codegen/{v}-{count}.asm"));fs::write(&p,&body).unwrap();pin(&mut pins,p);count+=1;}assert!(count>=2);}save(r("jobs.json"),&json!(jobs));for c in&cs{assert_eq!(hash(c["image"].as_str().unwrap()),c["image_sha256"]);pin(&mut pins,c["image"].as_str().unwrap());pin(&mut pins,c["request"].as_str().unwrap());}for e in fs::read_dir("/home/ubuntu/src/zopro-perf-work/sdk-control-copies/lagrange-cache").unwrap(){pin(&mut pins,e.unwrap().path());}for p in[VERIFY,X,MANIFEST]{pin(&mut pins,p);}for f in["make-capture.rs","capture-setup.rs","capture.rs","capture-helper","design.md","source-audit.json","identities.json","cases.json","jobs.json","prior-proof-sha256.json","native/result.json"]{pin(&mut pins,r(f));}save(r("pins.json"),&json!(pins));save(r("run-plan.json"),&json!({"version":1,"source_pins":r("pins.json"),"steps":steps}));fs::write(r("host-before.txt"),output(&["ps","-eo","pid,ppid,comm,pcpu,pmem,etimes","--sort=-pcpu"])).unwrap();println!("Prepared276steps27preflight93primary31blocklatency6profiles;15954SDK126freshGnark/ledger20755->20881prospective");}
